            }
        }

        Ok(entries)
    }

    /// Rewrite all entries (for updates).
    fn rewrite_all(&self, entries: &[FeedbackEntry]) -> Result<()> {
        self.ensure_dir()?;

        let mut file = File::create(&self.path)?;
