        assert!(matches!(method, DeliveryMethod::Email { .. }));
    }

    // --- Payload building tests ---

    #[test]
    fn build_title_includes_category_and_message() {
        let entry = test_entry("bundle install fails on M3 Macs");
        let title = build_title(&entry, "bug");
