            .unwrap();
        assert!(output.status.success(), "tag push failed");

        let fetcher = GitFetcher::new(temp.path().join("clones"));

        let sha = fetcher
            .resolve_ref(&bare_path.to_string_lossy(), Some("v1.0"))
            .unwrap();

